    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$(({Cut Length} / {Feed Rate} * 60 + {Pierces} * {Pierce Time}) / max(1, {Heads}) + {Shuttle Time} / {Parts per Sheet}) * {Cycle Time Factor}$q$, 9, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Bar and Tube - Plate cutting$q$, is_active = is_active OR machine_class IS NOT NULL
