-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Bar and Tube - Stock per part$q$, 12, 0),
    ($q$Bar and Tube - Plate per part$q$, 13, 0),
    ($q$Bar and Tube - Extrusion billet$q$, 16, 0),
    ($q$Bar and Tube - Saw cut$q$, 11, 3),
    ($q$Bar and Tube - Shear$q$, 7, 1),
    ($q$Bar and Tube - Tube laser$q$, 13, 1),
    ($q$Bar and Tube - Punching$q$, 7, 1),
    ($q$Bar and Tube - End forming$q$, 5, 9),
    ($q$Bar and Tube - Rotary draw bending$q$, 11, 1),
    ($q$Bar and Tube - Compression bending$q$, 7, 1),
    ($q$Bar and Tube - Bar bend brake$q$, 7, 1),
    ($q$Bar and Tube - Roll bending$q$, 8, 3),
    ($q$Bar and Tube - Profile 3 roll bend$q$, 8, 1),
    ($q$Bar and Tube - Profile CNC bend$q$, 6, 1),
    ($q$Bar and Tube - Plate cutting$q$, 9, 3),
    ($q$Bar and Tube - Plasma and torch cutting$q$, 7, 3),
    ($q$Bar and Tube - Extrusion$q$, 10, 1),
    ($q$Bar and Tube - Billet preheat$q$, 8, 1),
    ($q$Bar and Tube - Die preheat$q$, 2, 1)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Bar and Tube Fabrication$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1091: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
